solution:
build = [350.0, [45.5, 45.5, [12.0, 12.0]], [89.9, [19.9, 2.5]]]

def count(parts):
    n = 0
    for p in parts:
        if isinstance(p, list):
            n = n + count(p)
        else:
            n = n + 1
    return n

def total(parts):
    s = 0
    for p in parts:
        if isinstance(p, list):
            s = s + total(p)
        else:
            s = s + p
    return round(s, 2)

print(f"Parts: {count(build)}")
print(f"Quote: {total(build)}")
